function begin(){if(game.tutorial.completed&&game.stones.length+game.moveStones.length>=game.boxCapacity.stones){showDialog(storageCapacityDialog(game,'stones'));return}run(()=>{if(!game.tutorial.completed)stageId='tutorial';battle=E.startBattle(game,stageId);const loadingBattle=battle;loadingBattle.loading=true;prepareOriginalBattle({...battle.stage,clientMapId:battle.clientStage?.m_mapDataID,clientDungeonId:battle.clientStage?.m_dungeonID,clientChallengeStage:battle.clientStage?.m_stageNo,clientPrevLocalID:battle.clientStage?.m_localID,clientEnemyPackName:battle.clientStage?.enemyPackName,actorSpecies:[...battle.units.filter(u=>!u.isEnemy).map(u=>sp(u.speciesId).dex),...battle.phases.flat().map(row=>row.dex||sp(row.speciesId)?.dex)].filter(Boolean)}).then(ready=>{if(ready&&battle===loadingBattle)E.configureBattleWorld(battle,getOriginalBattleLayout());}).catch(console.error).finally(()=>{loadingBattle.loading=false});view='battle';ended=false;lastReward=null;failureDialogAt=null;render()})}
