function cookingResult(){if(cookingPresentation||!game.cooking?.ready)return;const cooking=structuredClone(game.cooking),knownSpecies=new Set(game.discovered),isNewRecipe=!game.records?.recipes?.includes(cooking.recipeId),station=game.activeCookingStation||0;const r=run(()=>E.claimCooking(game));if(r?.ok===false&&(r.reason==='monster-storage-full'||r.message?.includes('伙伴盒空间不足'))){showDialog(storageCapacityDialog(game,'monsters',r.required));return}if(!r?.ok)return;const recruits=r.monsters||[r.monster].filter(Boolean);for(const m of recruits)if(!game.discovered.includes(m.speciesId))game.discovered.push(m.speciesId);selected=r.monster?.uid||selected;view='camp';render();save();const p=cookingPresentation={station,cooking,recruits,knownSpecies,isNewRecipe,index:0,stage:'opening'};setOriginalCampPotPresentation(station,'select',{...cooking,recipeIndex:Math.max(0,E.RECIPES.findIndex(r=>r.id===cooking.recipeId))});setOriginalCampRecruitPresentation(station,null,clock,{visitors:recruits});showDialog('<section class="cooking-lifecycle" aria-label="打开料理锅"><div class="cook-opening-message">料理完成！</div></section>');p.timer=setTimeout(()=>{if(cookingPresentation!==p)return;p.stage='recipe';const recipeIndex=Math.max(0,E.RECIPES.findIndex(r=>r.id===cooking.recipeId)),recipe=E.RECIPES[recipeIndex],volume={normal:'',bronze:'大份',silver:'特大份',gold:'超大份'}[cooking.potId]||'';showDialog(nativeCookingResultUI({recipe,recipeIndex,quality:({普通:'',好:'好',非常好:'很好',极致:'特别棒',0:'',1:'好',2:'很好',3:'特别棒'}[cooking.tier]||''),volume,isNew:isNewRecipe,ingredients:cooking.ingredients.map(foodIcon),description:[COOK_MESSAGES.cook_recipe_desc[recipeIndex],COOK_MESSAGES.cook_recipe_poke[recipeIndex]]}));},0);}
async function showCookingVisitor(){const p=cookingPresentation;if(!p||!['recipe','recruit'].includes(p.stage))return;if(p.index>=p.recruits.length){closeDialog();render();return;}const afterRecipe=p.stage==='recipe',firstArrival=!p.arrivalsPlayed;p.stage='preparing';let m=p.recruits[p.index],species=sp(m.speciesId);showDialog('<section class="cooking-lifecycle" aria-label="伙伴来访"></section>');try{if(afterRecipe){p.stage='breaking';setOriginalCampPotPresentation(p.station,'break');await new Promise(resolve=>p.timer=setTimeout(resolve,originalPotAnimationDuration(p.cooking.potId,'break')*1000));if(cookingPresentation!==p)return;setOriginalCampPotPresentation(p.station,'idle');}p.stage='arriving';const loaded=(await Promise.all((firstArrival?p.recruits:[m]).map(visitor=>preloadOriginalActorPortraits([sp(visitor.speciesId)],{shiny:visitor.shiny})))).flat();if(loaded.some(v=>!v))throw Error('Recruit model unavailable');if(cookingPresentation!==p)return;if(firstArrival){const wipe=mountOriginalCookingWhiteWipe($('#overlay .dialog'));if(!await wipe.play('in')||cookingPresentation!==p){wipe.remove();return;}setOriginalCampRecruitPresentation(p.station,m,clock,{visitors:p.recruits,holdVisit:true});p.arrivalsPlayed=true;if(!await wipe.play('out')||cookingPresentation!==p){wipe.remove();return;}await new Promise(resolve=>p.timer=setTimeout(resolve,Math.max(0,recruitGroupDuration(p.recruits.length)-1)*1000));if(cookingPresentation!==p){wipe.remove();return;}if(!await wipe.play('in')){wipe.remove();return;}setOriginalCampRecruitPresentation(p.station,null,clock,{visitors:p.recruits,waiting:true});if(!await wipe.play('out')||cookingPresentation!==p){wipe.remove();return;}wipe.remove();}else setOriginalCampRecruitPresentation(p.station,m,clock,{visitors:p.recruits,focusOnly:true});const reveal=uid=>{const i=p.recruits.findIndex(v=>v.uid===uid);if(i>p.index){[p.recruits[p.index],p.recruits[i]]=[p.recruits[i],p.recruits[p.index]];m=p.recruits[p.index];species=sp(m.speciesId);}p.stage='focusing';setOriginalCampRecruitPresentation(p.station,m,clock,{visitors:p.recruits,focusOnly:true});p.timer=setTimeout(()=>{if(cookingPresentation!==p)return;p.stage='recruit';const isNew=!p.knownSpecies.has(m.speciesId);p.knownSpecies.add(m.speciesId);const voice=originalPokemonVoice(species.dex,0);if(audioUnlocked&&sound&&voice)audio.playEffect(voice.eventId).catch(console.error);showDialog(nativeRecruitUI({names:[species.name],monsterCount:game.monsters.length,capacity:game.boxCapacity.monsters,isNew,monster:m,species,game,monsterStats:E.monsterStats,expProgress:m=>m.level>=100?1:m.xp/E.nextLevelXp(m.level),isSlotUnlocked:E.isSlotUnlocked,slotUnlockLevel:E.slotUnlockLevel,moveName:id=>mv(id)?.name||id,moveIcon:skillIcon,stats:E.monsterStats(game,m),moves:m.moves.map(mv),hasNext:p.index+1<p.recruits.length}));},Math.max(RECRUIT_MOTION.zoomDuration,RECRUIT_MOTION.lookDuration)*1000);};if(firstArrival){p.stage='waiting';p.reveal=reveal;showDialog('<section class="cooking-lifecycle cook-visit-wait" aria-label="点击锅旁的新伙伴"><button data-action="cook-visitor-next" aria-label="查看来访伙伴">'+originalSprite('BC_feelicon_newface')+'</button>'+p.recruits.slice(p.index).map(v=>`<button class="cook-visitor-body" data-action="cook-visitor-next" data-visitor-uid="${v.uid}" aria-label="点击${esc(sp(v.speciesId).name)}完成招募"></button>`).join('')+'</section>');}else reveal();}catch(error){console.error(error);closeDialog();render();notify('伙伴已保存，展示资源加载失败，请返回营地查看。');}}


function doTrain(){if(!supports.length)return;showDialog(`<h2>开始${trainMode==='level'?'升级':'招式'}特训？</h2><p>${trainMode==='move'?`将更换招式 ${trainMoveIndex+1}：${esc(mv(mon(selected).moves[trainMoveIndex])?.name||mon(selected).moves[trainMoveIndex])}。<br>`:''}这 ${supports.length} 只支持宝可梦会在特训后离开。已装备方石会保留在库存中。</p><div class="dialog-actions"><button class="pink" data-action="close">取消</button><button data-action="confirm-train">开始特训</button></div>`)}
