 if(d.campPlace||d.campRotate){const id=d.campPlace||d.campRotate,current=campDecorationPlacements(game,M.DECORATIONS),item=M.DECORATIONS.find(v=>v.id===id);if(!item||!game.decorations.includes(id)||(d.campPlace&&!campCanPlace(item,+d.campSlot)))return;const r=gameSaveTransaction(game,E.saveGame,()=>{game.campPlacements??={};if(d.campPlace){const slot=+d.campSlot;for(const other of Object.keys(current))if(current[other].slot===slot&&other!==id)game.placedDecorations=game.placedDecorations.filter(v=>v!==other);if(!game.placedDecorations.includes(id))game.placedDecorations.push(id);game.campPlacements[id]={slot,turn:current[id]?.turn||0};}else if(current[id])game.campPlacements[id]={...current[id],turn:(current[id].turn+campRotationStep(item))%4};return{ok:true};});if(r?.ok===false)notify(r.message);render();showCampGoodsEditor();return;}
 if(d.trainMoveIndex!==undefined){const index=Number(d.trainMoveIndex);if(Number.isInteger(index)&&index>=0&&index<mon(selected).moves.length){trainMoveIndex=index;render();}}if(d.trainMode){trainMode=d.trainMode;supports=[];render()}if(d.support){if(d.support===selected||game.team.includes(d.support))return notify('目标和探险队成员不能作为支持伙伴');if(supports.includes(d.support))supports=supports.filter(id=>id!==d.support);else if(supports.length<4)supports.push(d.support);else return notify('最多 4 只支持伙伴');render()}if(d.supportRemove!==undefined){supports.splice(+d.supportRemove,1);render()}
