function showBattleDecision(collect){$('#overlay').innerHTML=nativeBattleConfirmation({collect});paint()}
function finishBattleDecision(collect){if(!battle||battle.rewardClaimed)return;if(battle.status==='fighting'){battle.status='retreated';battle.paused=false;ended=true;}settleBattleResult(collect)}
function settleBattleResult(collect){lastReward=E.claimBattle(game,battle,{collectFailedDrops:collect});if(lastReward?.ok===false){if(lastReward.reason==='save-failed'){battle.pendingCollectDecision=collect;showDialog(`<h2>奖励尚未保存</h2><p>本地保存失败，奖励和进度尚未提交。请检查浏览器存储空间后重试，暂时不要关闭页面。</p><div class="dialog-actions"><button data-action="retry-battle-save">重试保存奖励</button></div>`);}else showBattlePause();return}failureDialogAt=null;save();syncMusic();showStageClear()}






